DROP VIEW "public"."leaderboard_view";--> statement-breakpoint
CREATE VIEW "public"."leaderboard_view" AS (select row_number() over (order by round((count(case when "players"."winner" = true then 1 end) * 100.0 / count(*)), 2) desc, count(case when "players"."winner" = true then 1 end) desc, count(*) desc, avg("players"."score") asc) as "rank", "users"."id", "users"."name", "users"."username", "users"."avatar", count(case when "players"."winner" = true then 1 end) as "wins", count(*) as "total_games", round((count(case when "players"."winner" = true then 1 end) * 100.0 / count(*)), 2) as "win_rate" from "users" inner join "players" on "users"."id" = "players"."user_id" where "users"."deleted_at" is null and "players"."user_id" is not null group by "users"."id", "users"."name", "users"."username", "users"."avatar" having count(*) >= 10 order by round((count(case when "players"."winner" = true then 1 end) * 100.0 / count(*)), 2) desc, count(case when "players"."winner" = true then 1 end) desc, count(*) desc, avg("players"."score") asc);